"""Kitchen Sink page: GraphicsView, a canvas of shapes that are objects: a floor plan of
rectangles, an ellipse, lines, a polygon, a path (SVG path data), text and a group; the
furniture can be dragged (Movable), turned, zoomed, saved as a picture and printed."""

import os
import tempfile

from vp6 import *


class pgGraphicsView(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'GraphicsView'
        self.Width = 640
        self.Height = 440
        self.gvwPlan = GraphicsView(self, Left=16, Top=16, Width=460, Height=380,
                                    BackColor=0xF4F4F4, TabIndex=1,
                                    ToolTipText='Drag the furniture; click any shape')
        self.cmdTurn = CommandButton(self, Caption='&Turn the table', Left=490, Top=16, Width=134,
                                     Height=32, TabIndex=2)
        self.cmdAdd = CommandButton(self, Caption='&Add a chair', Left=490, Top=56, Width=134,
                                    Height=32, TabIndex=3)
        self.cmdZoomIn = CommandButton(self, Caption='Zoom &in', Left=490, Top=104, Width=65,
                                       Height=32, TabIndex=4)
        self.cmdZoomOut = CommandButton(self, Caption='&out', Left=559, Top=104, Width=65,
                                        Height=32, TabIndex=5)
        self.cmdFit = CommandButton(self, Caption='&Fit all', Left=490, Top=144, Width=134,
                                    Height=32, TabIndex=6)
        self.cmdSave = CommandButton(self, Caption='&Save picture', Left=490, Top=192, Width=134,
                                     Height=32, TabIndex=7,
                                     ToolTipText='SavePicture(gvwPlan.Picture, ...): the whole plan as a PNG')
        self.cmdPrint = CommandButton(self, Caption='&Print', Left=490, Top=232, Width=134,
                                      Height=32, TabIndex=8,
                                      ToolTipText='PrintOut: the plan on the Printer')
        self.lblItem = Label(self, Caption='', Left=16, Top=404, Width=608, Height=22, TabIndex=9)
    # endregion

    def Form_Load(self):
        items = self.gvwPlan.Items
        items.AddRect(10, 10, 300, 200, BorderWidth=3, Key="living")  # the rooms
        items.AddRect(310, 10, 120, 200, BorderWidth=3, Key="kitchen")
        items.AddRect(10, 210, 420, 120, BorderWidth=3, Key="bedroom")
        items.AddPath("M 120 210 L 120 180 Q 150 180 150 210", ForeColor=vpBlue)  # a door
        for text, x, y in (("Living room", 20, 20), ("Kitchen", 320, 20), ("Bedroom", 20, 220)):
            items.AddText(text, x, y, ForeColor=RGB(90, 90, 90), FontBold=True)
        table = items.AddEllipse(100, 70, 110, 70, FillColor=RGB(205, 160, 110), Key="table")
        table.Movable = table.Selectable = True
        bed = items.AddRect(250, 240, 150, 80, FillColor=RGB(160, 190, 230), Key="bed")
        bed.Movable = bed.Selectable = True
        items.AddPolygon([(340, 150), (420, 150), (420, 200)], FillColor=RGB(200, 200, 200),
                         Key="counter")
        items.AddLine(10, 340, 430, 340, ForeColor=vpRed, Key="scale")
        self.chairs = 0
        self.cmdAdd_Click()

    def cmdAdd_Click(self):
        # A chair: a group (seat and back) that moves as one
        self.chairs += 1
        items = self.gvwPlan.Items
        x = 60 + 30 * self.chairs
        seat = items.AddRect(x, 150, 20, 20, FillColor=RGB(120, 80, 50))
        back = items.AddRect(x, 146, 20, 5, FillColor=RGB(80, 50, 30))
        chair = items.AddGroup(seat, back, Key=f"chair{self.chairs}")
        chair.Movable = chair.Selectable = True
        self.lblItem.Caption = f"Chair {self.chairs} added ({items.Count} shapes)"

    def cmdTurn_Click(self):
        table = self.gvwPlan.Items("table")
        table.Rotation = (table.Rotation + 15) % 360

    def cmdZoomIn_Click(self):
        self.gvwPlan.Zoom = self.gvwPlan.Zoom * 1.25

    def cmdZoomOut_Click(self):
        self.gvwPlan.Zoom = self.gvwPlan.Zoom / 1.25

    def cmdFit_Click(self):
        self.gvwPlan.ZoomToFit()

    def cmdSave_Click(self):
        path = os.path.join(tempfile.gettempdir(), "vp6-plan.png")
        SavePicture(self.gvwPlan.Picture, path)
        self.lblItem.Caption = f"Saved as {path}"

    def cmdPrint_Click(self):
        self.gvwPlan.PrintOut()
        self.lblItem.Caption = f"Printed on {Printer.DeviceName}"

    def gvwPlan_ItemClick(self, Item):
        self.lblItem.Caption = f"ItemClick: a {Item.Kind} {Item.Key!r} at {Item.Left:.0f}, " \
                               f"{Item.Top:.0f}"

    def gvwPlan_ItemMoved(self, Item):
        self.lblItem.Caption = f"ItemMoved: {Item.Key} to {Item.Left:.0f}, {Item.Top:.0f}"

    def gvwPlan_SelectionChanged(self):
        selected = [item.Key for item in self.gvwPlan.SelectedItems]
        if selected:
            self.lblItem.Caption = f"SelectionChanged: {', '.join(selected)}"


if __name__ == "__main__":
    run(pgGraphicsView)
